import{_ as d,f as a,c as r,a6 as e}from"./chunks/framework.CJQKpl5I.js";const u=JSON.parse('{"title":"第 6 章 附录","description":"","frontmatter":{},"headers":[],"relativePath":"ch06_appendix.md","filePath":"ch06_appendix.md"}'),h={name:"ch06_appendix.md"};function l(i,t,o,b,n,s){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="第-6-章-附录" tabindex="-1">第 6 章 附录 <a class="header-anchor" href="#第-6-章-附录" aria-label="Permalink to &quot;第 6 章 附录&quot;">​</a></h1><h2 id="_6-1-官方考核结构" tabindex="-1">6.1 官方考核结构 <a class="header-anchor" href="#_6-1-官方考核结构" aria-label="Permalink to &quot;6.1 官方考核结构&quot;">​</a></h2><p>理论考试共 60 题，其中单项选择题 30 道、多项选择题 10 道、判断题 20 道。</p><table tabindex="0"><thead><tr><th>考核模块</th><th>占比</th><th>60 题中约</th></tr></thead><tbody><tr><td>人工智能基础理论</td><td>30%</td><td>18 题</td></tr><tr><td>国产操作系统技术基础</td><td>20%</td><td>12 题</td></tr><tr><td>国产软件技术基础</td><td>20%</td><td>12 题</td></tr><tr><td>智能体技术基础</td><td>20%</td><td>12 题</td></tr><tr><td>国产硬件技术基础</td><td>10%</td><td>6 题</td></tr></tbody></table><p>初赛只包含理论题，省赛包含理论题和实操题。</p><h2 id="_6-2-高频考点分布" tabindex="-1">6.2 高频考点分布 <a class="header-anchor" href="#_6-2-高频考点分布" aria-label="Permalink to &quot;6.2 高频考点分布&quot;">​</a></h2><p>以下考点在两套模拟卷中出现 2 次及以上，属于反复考核的内容：</p><ul><li>异构计算与加速器定位：GPU 并行特征、NPU 专用加速、异构协同</li><li>兼容性层次：ISA、API、ABI、运行库、依赖</li><li>跨架构迁移：二进制无法运行的原因、重新编译</li><li>故障排查：Permission denied、文件系统空间、依赖冲突、网络跨网段</li><li>Agent 闭环：观察结果进入下一步决策、错误累积</li><li>工具调用：Schema、参数校验、失败处理、副作用</li><li>提示注入：外部内容携带恶意指令、人工确认</li><li>多 Agent：角色分工、通信与协调开销</li><li>systemd：status、enable、reload、restart</li><li>混合精度与量化：FP16 减半、INT8 提速、精度损失</li><li>上下文窗口与长期记忆：Token 范围、外部持久化</li><li>监督学习与标签、梯度与学习率</li><li>RAG 与微调的区别、推理时检索</li><li>中间件：通用能力、消息队列削峰与可靠处理</li><li>NoSQL 与键值模型</li><li>目录执行权限与 umask</li></ul><h2 id="_6-3-判断题陷阱句式" tabindex="-1">6.3 判断题陷阱句式 <a class="header-anchor" href="#_6-3-判断题陷阱句式" aria-label="Permalink to &quot;6.3 判断题陷阱句式&quot;">​</a></h2><p>判断题的错误项普遍使用绝对化表述，出现以下句式时优先考虑判断为错误：</p><ul><li>只要……就……</li><li>一定 / 必定 / 必然</li><li>唯一 / 只</li><li>所有 / 全部 / 一切</li><li>完全 / 彻底 / 永远</li><li>无需……（省略必要环节）</li></ul><p>真题示例对应的绝对化表述：只要应用能启动就无兼容问题、增加 Agent 数量一定能线性提高质量、设备能识别就完成兼容验证、只比较数据条数即可迁移、有聊天窗口就具备完整 Agent 能力、跨架构迁移只改文件名即可、只要有工具描述就无需校验参数、提示注入只存在于用户直接输入、索引只加快读取无额外成本。</p><p>正向判断的题目通常描述机制事实，例如：观察结果指导下一步决策、长期记忆依赖外部持久化、量化降低资源但损失精度、API 兼容不保证 ABI 兼容。</p><h2 id="_6-4-易混概念对照" tabindex="-1">6.4 易混概念对照 <a class="header-anchor" href="#_6-4-易混概念对照" aria-label="Permalink to &quot;6.4 易混概念对照&quot;">​</a></h2><h3 id="精度格式" tabindex="-1">精度格式 <a class="header-anchor" href="#精度格式" aria-label="Permalink to &quot;精度格式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>格式</th><th>字节数</th><th>用途</th></tr></thead><tbody><tr><td>FP32</td><td>4 字节</td><td>训练基准精度</td></tr><tr><td>FP16</td><td>2 字节</td><td>混合精度计算，显存减半、吞吐翻倍</td></tr><tr><td>BF16</td><td>2 字节</td><td>数值范围大，训练稳定</td></tr><tr><td>INT8</td><td>1 字节</td><td>推理量化，吞吐约 4 倍提升</td></tr></tbody></table><h3 id="采样策略" tabindex="-1">采样策略 <a class="header-anchor" href="#采样策略" aria-label="Permalink to &quot;采样策略&quot;">​</a></h3><table tabindex="0"><thead><tr><th>策略</th><th>机制</th></tr></thead><tbody><tr><td>贪心</td><td>每步取概率最高的 Token</td></tr><tr><td>Top-k</td><td>固定保留前 K 个候选</td></tr><tr><td>Top-p</td><td>按累计概率阈值动态选取候选</td></tr><tr><td>温度</td><td>缩放概率分布控制随机性</td></tr></tbody></table><h3 id="注意力变体" tabindex="-1">注意力变体 <a class="header-anchor" href="#注意力变体" aria-label="Permalink to &quot;注意力变体&quot;">​</a></h3><table tabindex="0"><thead><tr><th>变体</th><th>机制</th><th>特点</th></tr></thead><tbody><tr><td>MHA</td><td>每头独立 QKV</td><td>表达力强，计算开销大</td></tr><tr><td>MQA</td><td>多头共享同一组 K、V</td><td>减少 KV Cache 占用</td></tr><tr><td>GQA</td><td>若干头共享 KV</td><td>MHA 与 MQA 的折中</td></tr><tr><td>MLA</td><td>压缩 KV 表示</td><td>大幅降低推理成本，DeepSeek 采用</td></tr><tr><td>FlashAttention</td><td>分块计算、减少显存读写</td><td>加速注意力运算</td></tr></tbody></table><h3 id="l1-与-l2-正则" tabindex="-1">L1 与 L2 正则 <a class="header-anchor" href="#l1-与-l2-正则" aria-label="Permalink to &quot;L1 与 L2 正则&quot;">​</a></h3><table tabindex="0"><thead><tr><th>正则</th><th>效果</th><th>机制</th></tr></thead><tbody><tr><td>L1</td><td>权重稀疏（部分归零）</td><td>零点附近梯度恒定，推动精确归零</td></tr><tr><td>L2</td><td>权重整体变小（不归零）</td><td>梯度随权重线性缩小</td></tr></tbody></table><h3 id="信号" tabindex="-1">信号 <a class="header-anchor" href="#信号" aria-label="Permalink to &quot;信号&quot;">​</a></h3><table tabindex="0"><thead><tr><th>信号</th><th>行为</th></tr></thead><tbody><tr><td>SIGTERM</td><td>请求可控终止，进程可捕获处理</td></tr><tr><td>SIGKILL</td><td>内核强制终止，不可捕获</td></tr></tbody></table><h3 id="链接类型" tabindex="-1">链接类型 <a class="header-anchor" href="#链接类型" aria-label="Permalink to &quot;链接类型&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>机制</th><th>特点</th></tr></thead><tbody><tr><td>硬链接</td><td>共享同一 inode</td><td>不能跨文件系统、不能指向目录</td></tr><tr><td>软链接</td><td>指向路径的特殊文件</td><td>可跨文件系统、可指向目录，目标被删则失效</td></tr></tbody></table><h3 id="raid-级别" tabindex="-1">RAID 级别 <a class="header-anchor" href="#raid-级别" aria-label="Permalink to &quot;RAID 级别&quot;">​</a></h3><table tabindex="0"><thead><tr><th>级别</th><th>机制</th><th>特点</th></tr></thead><tbody><tr><td>RAID0</td><td>条带化</td><td>提升性能，无冗余</td></tr><tr><td>RAID1</td><td>镜像</td><td>提供冗余，容量减半</td></tr><tr><td>RAID5</td><td>奇偶校验</td><td>兼顾性能与冗余，单盘故障可重建</td></tr></tbody></table><h3 id="学习范式" tabindex="-1">学习范式 <a class="header-anchor" href="#学习范式" aria-label="Permalink to &quot;学习范式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>范式</th><th>数据</th><th>目标</th></tr></thead><tbody><tr><td>监督学习</td><td>带标签</td><td>学习映射</td></tr><tr><td>无监督学习</td><td>无标签</td><td>发现结构</td></tr><tr><td>强化学习</td><td>环境奖励</td><td>学习策略</td></tr></tbody></table><h3 id="rag-与微调" tabindex="-1">RAG 与微调 <a class="header-anchor" href="#rag-与微调" aria-label="Permalink to &quot;RAG 与微调&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方式</th><th>机制</th><th>知识更新</th></tr></thead><tbody><tr><td>RAG</td><td>推理时检索外部知识注入上下文</td><td>无需修改模型参数</td></tr><tr><td>微调</td><td>用数据更新模型参数</td><td>修改模型参数</td></tr></tbody></table><h3 id="记忆类型" tabindex="-1">记忆类型 <a class="header-anchor" href="#记忆类型" aria-label="Permalink to &quot;记忆类型&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>存储位置</th><th>范围</th></tr></thead><tbody><tr><td>短期记忆</td><td>上下文窗口</td><td>一次会话，容量有限</td></tr><tr><td>长期记忆</td><td>外部持久化存储</td><td>跨会话，需时效性与相关性管理</td></tr></tbody></table><h3 id="并行策略" tabindex="-1">并行策略 <a class="header-anchor" href="#并行策略" aria-label="Permalink to &quot;并行策略&quot;">​</a></h3><table tabindex="0"><thead><tr><th>策略</th><th>切分</th><th>通信</th></tr></thead><tbody><tr><td>数据并行</td><td>数据批次</td><td>梯度同步，量大</td></tr><tr><td>模型并行</td><td>模型层</td><td>中等</td></tr><tr><td>流水线并行</td><td>层分段</td><td>开销小</td></tr><tr><td>张量并行</td><td>单层参数</td><td>频率极高</td></tr></tbody></table><h3 id="液冷分类" tabindex="-1">液冷分类 <a class="header-anchor" href="#液冷分类" aria-label="Permalink to &quot;液冷分类&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>接触方式</th><th>特点</th></tr></thead><tbody><tr><td>直接接触式</td><td>冷却液接触芯片</td><td>效率高，要求绝缘</td></tr><tr><td>冷板液冷</td><td>经冷板导热</td><td>安全，兼容性好</td></tr></tbody></table><h3 id="冷板材料" tabindex="-1">冷板材料 <a class="header-anchor" href="#冷板材料" aria-label="Permalink to &quot;冷板材料&quot;">​</a></h3><table tabindex="0"><thead><tr><th>材料</th><th>优点</th><th>限制</th></tr></thead><tbody><tr><td>铜</td><td>导热高、耐腐蚀</td><td>成本高、密度大</td></tr><tr><td>铝</td><td>质轻、成本低</td><td>易电偶腐蚀，限全铝回路</td></tr></tbody></table><h2 id="_6-5-主要命令速查" tabindex="-1">6.5 主要命令速查 <a class="header-anchor" href="#_6-5-主要命令速查" aria-label="Permalink to &quot;6.5 主要命令速查&quot;">​</a></h2><p>判断题常考命令用途混淆，例如 systemctl status 用于查看状态，enable 配置开机自启。以下按功能列出命令，注意区分相近命令。</p><h3 id="文件与权限" tabindex="-1">文件与权限 <a class="header-anchor" href="#文件与权限" aria-label="Permalink to &quot;文件与权限&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>用途</th></tr></thead><tbody><tr><td>ls</td><td>列出目录内容</td></tr><tr><td>cd</td><td>切换目录</td></tr><tr><td>mkdir</td><td>创建目录，-p 一次创建多层</td></tr><tr><td>touch</td><td>创建空文件</td></tr><tr><td>cp</td><td>复制文件或目录</td></tr><tr><td>mv</td><td>移动或重命名</td></tr><tr><td>rm</td><td>删除文件或目录</td></tr><tr><td>cat</td><td>查看文件内容</td></tr><tr><td>less</td><td>分页查看文件</td></tr><tr><td>vim</td><td>编辑文件</td></tr><tr><td>chmod</td><td>修改权限</td></tr><tr><td>chown</td><td>修改所有者</td></tr><tr><td>find</td><td>按条件查找文件</td></tr><tr><td>grep</td><td>在文本中搜索匹配行</td></tr><tr><td>ln</td><td>创建链接，软链接指向路径</td></tr></tbody></table><h3 id="系统信息采集" tabindex="-1">系统信息采集 <a class="header-anchor" href="#系统信息采集" aria-label="Permalink to &quot;系统信息采集&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>用途</th></tr></thead><tbody><tr><td>whoami</td><td>当前登录用户名</td></tr><tr><td>hostname</td><td>主机名</td></tr><tr><td>uname -m</td><td>CPU 架构</td></tr><tr><td>uname -r</td><td>内核版本</td></tr><tr><td>date</td><td>当前日期和时间</td></tr><tr><td>df -h</td><td>分区空间使用情况</td></tr><tr><td>free -h</td><td>内存使用情况</td></tr><tr><td>ip addr</td><td>网络接口及地址</td></tr></tbody></table><h3 id="打包压缩" tabindex="-1">打包压缩 <a class="header-anchor" href="#打包压缩" aria-label="Permalink to &quot;打包压缩&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>用途</th></tr></thead><tbody><tr><td>tar -czvf 包.tar.gz 目录</td><td>打包并 gzip 压缩目录</td></tr><tr><td>tar -tzvf 包.tar.gz</td><td>列出压缩包内容</td></tr><tr><td>tar -xzvf 包.tar.gz</td><td>解压到当前目录</td></tr></tbody></table><h3 id="磁盘与存储" tabindex="-1">磁盘与存储 <a class="header-anchor" href="#磁盘与存储" aria-label="Permalink to &quot;磁盘与存储&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>用途</th></tr></thead><tbody><tr><td>df</td><td>查看分区空间使用</td></tr><tr><td>du</td><td>查看目录或文件占用</td></tr><tr><td>fdisk</td><td>磁盘分区工具</td></tr><tr><td>mount</td><td>挂载文件系统</td></tr><tr><td>free</td><td>查看内存使用</td></tr><tr><td>swapoff/swapon</td><td>关闭或启用交换空间</td></tr></tbody></table><h3 id="进程与信号" tabindex="-1">进程与信号 <a class="header-anchor" href="#进程与信号" aria-label="Permalink to &quot;进程与信号&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>用途</th></tr></thead><tbody><tr><td>ps</td><td>查看进程快照</td></tr><tr><td>top</td><td>动态查看进程资源占用</td></tr><tr><td>kill</td><td>发送信号终止进程</td></tr><tr><td>nohup</td><td>终端关闭后继续运行</td></tr><tr><td>jobs</td><td>查看后台任务</td></tr><tr><td>fg</td><td>把后台任务调回前台</td></tr></tbody></table><p>信号：SIGTERM 请求可控终止，SIGKILL 内核强制终止且不可捕获。</p><h3 id="systemctl-子命令" tabindex="-1">systemctl 子命令 <a class="header-anchor" href="#systemctl-子命令" aria-label="Permalink to &quot;systemctl 子命令&quot;">​</a></h3><table tabindex="0"><thead><tr><th>子命令</th><th>用途</th></tr></thead><tbody><tr><td>status</td><td>查看服务状态</td></tr><tr><td>start</td><td>启动服务</td></tr><tr><td>stop</td><td>停止服务</td></tr><tr><td>restart</td><td>重启服务</td></tr><tr><td>reload</td><td>重载配置，可用性取决于服务能力</td></tr><tr><td>enable</td><td>配置开机自启</td></tr><tr><td>disable</td><td>取消开机自启</td></tr></tbody></table><blockquote><p>易混：<code>enable</code> 只配置开机自启，不等同于当前服务已运行；<code>start</code> 才是立即启动。</p></blockquote><h3 id="日志" tabindex="-1">日志 <a class="header-anchor" href="#日志" aria-label="Permalink to &quot;日志&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>用途</th></tr></thead><tbody><tr><td>journalctl</td><td>查看 systemd 日志</td></tr><tr><td>tail -f</td><td>实时跟踪日志文件</td></tr><tr><td>dmesg</td><td>查看内核日志</td></tr></tbody></table><h3 id="网络" tabindex="-1">网络 <a class="header-anchor" href="#网络" aria-label="Permalink to &quot;网络&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>用途</th></tr></thead><tbody><tr><td>ip</td><td>查看配置地址和路由</td></tr><tr><td>ss</td><td>查看端口监听和连接</td></tr><tr><td>ping</td><td>测试连通性</td></tr><tr><td>traceroute</td><td>追踪路由路径</td></tr><tr><td>ssh</td><td>远程登录</td></tr><tr><td>scp</td><td>远程复制文件</td></tr><tr><td>nc</td><td>网络调试工具</td></tr><tr><td>curl</td><td>发送 HTTP 请求</td></tr></tbody></table><h3 id="软件包管理" tabindex="-1">软件包管理 <a class="header-anchor" href="#软件包管理" aria-label="Permalink to &quot;软件包管理&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>用途</th></tr></thead><tbody><tr><td>apt update</td><td>更新包索引</td></tr><tr><td>apt install</td><td>安装软件包</td></tr><tr><td>apt remove</td><td>卸载软件包</td></tr><tr><td>apt search</td><td>搜索软件包</td></tr><tr><td>dpkg</td><td>直接操作 deb 包</td></tr></tbody></table><h3 id="用户与权限管理" tabindex="-1">用户与权限管理 <a class="header-anchor" href="#用户与权限管理" aria-label="Permalink to &quot;用户与权限管理&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>用途</th></tr></thead><tbody><tr><td>useradd</td><td>创建用户</td></tr><tr><td>passwd</td><td>设置密码</td></tr><tr><td>su</td><td>切换用户</td></tr><tr><td>sudo</td><td>以管理员权限执行</td></tr><tr><td>id</td><td>查看当前用户信息</td></tr></tbody></table><h3 id="其他常用" tabindex="-1">其他常用 <a class="header-anchor" href="#其他常用" aria-label="Permalink to &quot;其他常用&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>用途</th></tr></thead><tbody><tr><td>man</td><td>查看命令帮助</td></tr><tr><td>which</td><td>查看命令所在路径</td></tr><tr><td>echo</td><td>输出内容</td></tr><tr><td>history</td><td>查看命令历史</td></tr><tr><td>crontab</td><td>配置定时任务</td></tr><tr><td>tar</td><td>打包压缩文件</td></tr><tr><td>unzip</td><td>解压 zip 文件</td></tr></tbody></table><h2 id="_6-6-排障思路速查" tabindex="-1">6.6 排障思路速查 <a class="header-anchor" href="#_6-6-排障思路速查" aria-label="Permalink to &quot;6.6 排障思路速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>故障现象</th><th>排查重点</th></tr></thead><tbody><tr><td>Permission denied</td><td>运行用户、目标文件或目录权限</td></tr><tr><td>文件系统空间不足</td><td>大文件、日志、临时文件、被删除仍占用的文件</td></tr><tr><td>安装依赖冲突</td><td>依赖链、软件源一致性、包索引</td></tr><tr><td>跨架构启动失败</td><td>ISA、ABI、运行库、目标架构构建</td></tr><tr><td>跨网段访问失败</td><td>默认网关、路由</td></tr><tr><td>高 CPU</td><td>进程 PID 与命令、日志、占用持续性、业务关联</td></tr><tr><td>新设备不可识别</td><td>对应驱动支持</td></tr><tr><td>服务仅本机可访问</td><td>监听地址是否绑定回环接口</td></tr></tbody></table>',68)])])}const m=d(h,[["render",l]]);export{u as __pageData,m as default};
